<?php
/**
 * Create the FaS Fluent Forms from the repo definitions in data/forms/.
 * Run on the server: wp eval-file deploy/create-fluent-forms.php
 * Idempotent: existing forms are skipped unless FAS_FF_UPDATE=1 is set in the
 * environment, in which case fields and settings are refreshed from the repo.
 * Form definitions are generated by tools/gen_forms.py.
 */

if (!defined('ABSPATH')) {
    exit;
}

global $wpdb;
$forms_table = $wpdb->prefix . 'fluentform_forms';
$meta_table  = $wpdb->prefix . 'fluentform_form_meta';
$base = dirname(__FILE__) . '/../data/forms';
$update = getenv('FAS_FF_UPDATE') === '1';

foreach (array('register', 'submit', 'claim') as $key) {
    $file = "$base/$key-form.json";
    if (!file_exists($file)) {
        WP_CLI::warning("missing $file");
        continue;
    }
    $doc = json_decode(file_get_contents($file), true);
    if (!$doc || empty($doc['form_fields']) || empty($doc['formSettings'])) {
        WP_CLI::warning("bad JSON in $file");
        continue;
    }
    $option_key = 'fas_fluent_' . $key . '_form_id';
    $existing_id = (int) get_option($option_key, 0);
    $exists = $existing_id && $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM $forms_table WHERE id = %d", $existing_id
    ));
    $fields_json = wp_json_encode($doc['form_fields']);
    $settings_json = wp_json_encode($doc['formSettings']);

    if ($exists && !$update) {
        WP_CLI::log("$key: form #$existing_id exists, skipped (set FAS_FF_UPDATE=1 to refresh)");
        continue;
    }
    if ($exists && $update) {
        $wpdb->update($forms_table,
            array('title' => $doc['title'], 'form_fields' => $fields_json, 'status' => 'published'),
            array('id' => $existing_id));
        $wpdb->delete($meta_table, array('form_id' => $existing_id, 'meta_key' => 'formSettings'));
        $wpdb->insert($meta_table, array(
            'form_id' => $existing_id, 'meta_key' => 'formSettings', 'value' => $settings_json,
        ));
        WP_CLI::success("$key: form #$existing_id refreshed from repo");
        continue;
    }
    $wpdb->insert($forms_table, array(
        'title' => $doc['title'],
        'status' => 'published',
        'form_fields' => $fields_json,
        'has_payment' => 0,
        'type' => 'form',
        'created_by' => 1,
        'created_at' => current_time('mysql'),
        'updated_at' => current_time('mysql'),
    ));
    $form_id = (int) $wpdb->insert_id;
    $wpdb->insert($meta_table, array(
        'form_id' => $form_id, 'meta_key' => 'formSettings', 'value' => $settings_json,
    ));
    update_option($option_key, $form_id);
    WP_CLI::success("$key: created form #$form_id ({$doc['title']})");
}
